function parseAmount(str) {
    // German input: 15.000.000 or 4,5
    var s = String(str).replace(/\s/g, '');
    if (s.indexOf(',') !== -1 || /^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
    var n = Number(s.replace(/[^0-9.]/g, ''));
    return isFinite(n) ? n : 0;
  }
